import React from "react";
import "./Services.css";

const services = [
{
name: "Electrician",
img: "[https://static.vecteezy.com/system/resources/thumbnails/010/508/352/small_2x/side-view-of-a-handsome-asian-electrician-repairing-an-electrical-box-with-pliers-in-the-corridor-free-photo.jpg](https://static.vecteezy.com/system/resources/thumbnails/010/508/352/small_2x/side-view-of-a-handsome-asian-electrician-repairing-an-electrical-box-with-pliers-in-the-corridor-free-photo.jpg)"
},
{
name: "Plumber",
img: "[https://images.unsplash.com/photo-1563453392212-326f5e854473?w=800](https://images.unsplash.com/photo-1563453392212-326f5e854473?w=800)"
},
{
name: "Carpenter",
img: "[https://images.unsplash.com/photo-1519710164239-da123dc03ef4?w=800](https://images.unsplash.com/photo-1519710164239-da123dc03ef4?w=800)"
},
{
name: "House Cleaning",
img: "[https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?w=800](https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?w=800)"
},
{
name: "AC Repair",
img: "[https://images.unsplash.com/photo-1581090700227-1e37b190418e?w=800](https://images.unsplash.com/photo-1581090700227-1e37b190418e?w=800)"
},
{
name: "Painting",
img: "[https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800](https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800)"
},
{
name: "Beauty & Salon",
img: "[https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800](https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800)"
},
{
name: "Massage Service",
img: "[https://www.contactmonkey.com/cm_wp/wp-content/uploads/2023/02/Text-Messaging-Services-for-Business_650.jpg](https://www.contactmonkey.com/cm_wp/wp-content/uploads/2023/02/Text-Messaging-Services-for-Business_650.jpg)"
},
{
name: "Pest Control",
img: "[https://images.unsplash.com/photo-1620121692029-d088224ddc74?w=800](https://images.unsplash.com/photo-1620121692029-d088224ddc74?w=800)"
},
{
name: "Appliance Repair",
img: "[https://highnappliance.com/wp-content/uploads/2021/09/shutterstock_1876520710-scaled.jpg](https://highnappliance.com/wp-content/uploads/2021/09/shutterstock_1876520710-scaled.jpg)"
},
{
name: "Gardening",
img: "[https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800](https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800)"
},
{
name: "Chef / Cooking",
img: "[https://images.unsplash.com/photo-1546069901-eacef0df6022?w=800](https://images.unsplash.com/photo-1546069901-eacef0df6022?w=800)"
},
{
name: "Pet Care",
img: "[https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800](https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800)"
},
{
name: "Laptop Repair",
img: "[https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=800](https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=800)"
}
];

function Services() {
return ( <div className="services-container"> <h2 className="services-title">Our Services</h2> <div className="services-grid">
{services.map((service, index) => ( <div key={index} className="service-card"> <img src={service.img} alt={service.name} className="service-img" /> <h3 className="service-name">{service.name}</h3> </div>
))} </div> </div>
);
}

export default Services;
